add_action( 'admin_notices', 'perfectpixel_products_without_weight_notice' );

function perfectpixel_products_without_weight_notice() {
	$screen = get_current_screen();
	if ( ! $screen || 'edit-product' !== $screen->id || ! current_user_can( 'edit_products' ) ) {
		return;
	}
	$ids = get_posts(
		array(
			'post_type'      => array( 'product', 'product_variation' ),
			'post_status'    => 'publish',
			'fields'         => 'ids',
			'posts_per_page' => 30,
			'no_found_rows'  => true,
			'meta_query'     => array(
				'relation' => 'AND',
				array(
					'relation' => 'OR',
					array( 'key' => '_weight', 'compare' => 'NOT EXISTS' ),
					array( 'key' => '_weight', 'value' => '' ),
				),
				array(
					'relation' => 'OR',
					array( 'key' => '_virtual', 'compare' => 'NOT EXISTS' ),
					array( 'key' => '_virtual', 'value' => 'no' ),
				),
			),
		)
	);
	$links = array();
	foreach ( $ids as $id ) {
		$product = wc_get_product( $id );
		if ( ! $product || $product->is_type( array( 'variable', 'grouped', 'external' ) ) || ! $product->needs_shipping() || $product->get_weight() ) {
			continue;
		}
		$edit_id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
		$links[] = '<a href="' . esc_url( get_edit_post_link( $edit_id ) ) . '">' . esc_html( $product->get_name() ) . '</a>';
	}
	if ( $links ) {
		echo '<div class="notice notice-warning"><p><strong>Προϊόντα χωρίς βάρος:</strong> ' . implode( ', ', $links ) . '</p></div>';
	}
}
